import os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
import re
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(g[r+i][c+j]==2 for i in range(2) for j in range(2)):
                blocks.append((r,c))
                for i in range(2):
                    for j in range(2):
                        out[r+i][c+j]=2
    for r,c in blocks:
        TL=g[r-1][c-1] if r>0 and c>0 else 0
        TR=g[r-1][c+2] if r>0 and c+2<w else 0
        BL=g[r+2][c-1] if r+2<h and c>0 else 0
        BR=g[r+2][c+2] if r+2<h and c+2<w else 0
        # clockwise: TL->TR, TR->BR, BR->BL, BL->TL
        rays={(r-1,c-1,-1,-1):BL,(r-1,c+2,-1,1):TL,(r+2,c-1,1,-1):BR,(r+2,c+2,1,1):TR}
        for (sr,sc,dr,dc),v in rays.items():
            rr,cc=sr,sc
            while 0<=rr<h and 0<=cc<w:
                out[rr][cc]=v; rr+=dr; cc+=dc
    return out

o=transform(G['Demo pair 1 input'])
print(o==G['Demo pair 1 output'])
res=transform(G['Test input'])
for row in res: print(' '.join(map(str,row)))
